// DEMO-1 — host kill ladder: SIGTERM, wait grace_ms, then SIGKILL.
// Reused by the internal MCP wrapper; DEMO-3 promotes it to the public surface.

use std::time::{Duration, Instant};

pub struct SessionId(pub String);

#[derive(Debug, PartialEq, Eq)]
pub enum KillOutcome {
    Terminated,
    Forced,
    AlreadyExited,
}

pub fn kill_agent(_session_id: &SessionId, grace_ms: u32) -> KillOutcome {
    let deadline = Instant::now() + Duration::from_millis(grace_ms as u64);
    // Pretend we SIGTERM'd and waited.
    while Instant::now() < deadline {
        if process_exited() {
            return KillOutcome::Terminated;
        }
        std::thread::sleep(Duration::from_millis(50));
    }
    sigkill();
    KillOutcome::Forced
}

fn process_exited() -> bool { true }
fn sigkill() {}

